"use strict";(globalThis.webpackChunkogd_handbuch=globalThis.webpackChunkogd_handbuch||[]).push([[255],{3451(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/ogd-handbook/","label":"1. Einstieg","docId":"startseite","unlisted":false},{"type":"category","label":"2. OGD Grundlagen","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/ogd-handbook/ogd_grundlagen/was-ist-ogd","label":"Was ist OGD?","docId":"ogd_grundlagen/was-ist-ogd","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/prinzipien","label":"Zentrale Prinzipien","docId":"ogd_grundlagen/prinzipien","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/fair-care","label":"Leitmotiv FAIR & CARE","docId":"ogd_grundlagen/fair-care","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/ogd-landschaft","label":"OGD-Landschaft Schweiz","docId":"ogd_grundlagen/ogd-landschaft","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/ogd-nutzen","label":"OGD Nutzen","docId":"ogd_grundlagen/ogd-nutzen","unlisted":false}]},{"type":"category","label":"3. OGD im Kanton Z\xfcrich","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/ogd-handbook/ogd_kanton_zh/transparenz","label":"Transparenz in der Verwaltung","docId":"ogd_kanton_zh/transparenz","unlisted":false}]},{"type":"link","href":"/ogd-handbook/struktur","label":"4. Daten","docId":"struktur","unlisted":false},{"type":"link","href":"/ogd-handbook/metadaten","label":"5. Metadaten","docId":"metadaten","unlisted":false},{"type":"link","href":"/ogd-handbook/anleitungen","label":"6. Anleitungen","docId":"anleitungen","unlisted":false},{"type":"link","href":"/ogd-handbook/kontakt","label":"7. Kontakt","docId":"kontakt","unlisted":false}]},"docs":{"anleitungen":{"id":"anleitungen","title":"6. Anleitungen","description":"","sidebar":"tutorialSidebar"},"kontakt":{"id":"kontakt","title":"7. Kontakt","description":"","sidebar":"tutorialSidebar"},"metadaten":{"id":"metadaten","title":"5. Metadaten","description":"","sidebar":"tutorialSidebar"},"ogd_grundlagen/fair-care":{"id":"ogd_grundlagen/fair-care","title":"Leitmotiv FAIR & CARE","description":"Die Leitmotive \\"FAIR & CARE\\" konkretisieren die Anforderungen an Qualit\xe4t und verantwortungsvollen Umgang mit Open Government Data. Dieses Leitmotiv verbindet technische Offenheit mit verantwortungsvollem Handeln.","sidebar":"tutorialSidebar"},"ogd_grundlagen/ogd-landschaft":{"id":"ogd_grundlagen/ogd-landschaft","title":"OGD-Landschaft Schweiz","description":"Open Government Data werden in der Schweiz auf verschiedenen Ebenen bereitgestellt - von Gemeinden und Kantonen \xfcber den Bund bis hin zur europ\xe4ischen Ebene. Viele Kantone und gr\xf6ssere Gemeinden betreiben eigenst\xe4ndige Datenkataloge mit eigener Datenhaltung. Sie sind der Ursprung vieler Datens\xe4tze und verantwortlich f\xfcr deren Pflege und Qualit\xe4t.","sidebar":"tutorialSidebar"},"ogd_grundlagen/ogd-nutzen":{"id":"ogd_grundlagen/ogd-nutzen","title":"OGD Nutzen","description":"Offene Daten entfalten ihren Nutzen erst, wenn sie auch tats\xe4chlich verwendet werden. Ein aktiver Feedbackloop zwischen Nutzenden und Datenpublizierenden ist dabei zentral: Nur so k\xf6nnen fehlende Datens\xe4tze identifiziert, bestehende verbessert und das Angebot gezielt weiterentwickelt werden.","sidebar":"tutorialSidebar"},"ogd_grundlagen/prinzipien":{"id":"ogd_grundlagen/prinzipien","title":"Zentrale Prinzipien","description":"Damit offene Verwaltungsdaten optimal genutzt werden und Wirkung entfalten k\xf6nnen, m\xfcssen sie bestimmten Grunds\xe4tzen folgen. Diese Grunds\xe4tze sind in der International Open Data Charter festgehalten - einem international anerkannten Rahmenwerk f\xfcr offene Daten.","sidebar":"tutorialSidebar"},"ogd_grundlagen/was-ist-ogd":{"id":"ogd_grundlagen/was-ist-ogd","title":"Was ist OGD?","description":"Dieses Kapitel erkl\xe4rt, was offene Beh\xf6rdendaten (OGD) sind, warum sie wichtig sind und wo sie genutzt werden k\xf6nnen.","sidebar":"tutorialSidebar"},"ogd_kanton_zh/transparenz":{"id":"ogd_kanton_zh/transparenz","title":"Transparenz in der Verwaltung","description":"Der Kanton Z\xfcrich kennt seit 2006 das \xd6ffentlichkeitsprinzip, das Verwaltungshandeln auch f\xfcr Aussenstehende nachvollziehbar machen will. Mit Einf\xfchrung des \xd6ffentlichkeitsprinzip fiel auch das Amtsgeheimnis, das Verwaltungshandeln bis dahin pr\xe4gte. Heute wird unterschieden zwischen Information die \xf6ffentlich sein darf, Information, die intern bleiben sollte, Information, die vertraulich ist und Information, die geheim bleiben muss. Diese Klassifizierung bestimmt den Personenkreis, dem die Information per se zug\xe4nglich ist. Das \xd6ffentlichkeitsprinzip verpflichtet einerseits staatliche Stellen, mit Information von allgemeinem Interesse von sich aus an die \xd6ffentlichkeit zu gelangen, also eine aktive Informationspolitik zu betreiben. Andererseits hat jede Person grunds\xe4tzlich das Recht auf Zugang zu Informationen, die bei staatlichen Stellen vorhanden sind. Angefragte staatliche Stellen sind verpflichtet, solche Anfragen zu beantworten.","sidebar":"tutorialSidebar"},"startseite":{"id":"startseite","title":"1. Einstieg","description":"","sidebar":"tutorialSidebar"},"struktur":{"id":"struktur","title":"4. Daten","description":"","sidebar":"tutorialSidebar"}}}}')}}]);